릴리즈 상세는 <https://github.com/hkjang/nexabuilder/releases>.
plugins {
    java
    id("org.springframework.boot") version "4.1.1"
    id("io.spring.dependency-management") version "1.1.7"
    groovy
}

group = "com.nexabuilder"
version = "1.19.0"

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // Spring Boot Starters
    implementation("org.springframework.boot:spring-boot-starter-web")
    implementation("org.springframework.boot:spring-boot-starter-data-jpa")
    implementation("org.springframework.boot:spring-boot-starter-security")
    // OAuth2 client for OIDC SSO (Google / Keycloak / Okta / Azure AD …).
    // Activated at runtime only when spring.security.oauth2.client.registration.*
    // properties are present; absent config => zero overhead.
    implementation("org.springframework.boot:spring-boot-starter-oauth2-client")
    implementation("org.springframework.boot:spring-boot-starter-validation")
    // Boot 4 는 기본 JSON 을 Jackson 3(tools.jackson) 으로 바꿨다. 이 저장소의
    // 100개 파일이 com.fasterxml.jackson 의 ObjectMapper 를 주입받으므로, 그
    // 빈을 계속 내주는 공식 호환 모듈을 함께 올린다. Jackson 3 으로 옮기는 것은
    // API 가 달라(ObjectMapper 불변화, 검사 예외 제거) 따로 다룰 일이다.
    implementation("org.springframework.boot:spring-boot-jackson2")
    implementation("org.springframework.boot:spring-boot-starter-actuator")
    // Prometheus scrape endpoint at /actuator/prometheus (see docs/operations/monitoring.md).
    runtimeOnly("io.micrometer:micrometer-registry-prometheus")
    // OpenTelemetry tracing (#66). The bridge wires Spring's Observation
    // API to OTel spans; the OTLP exporter ships them to a collector
    // when management.otlp.tracing.endpoint is configured. Absent
    // config = no overhead beyond Observation creation that's already
    // happening for the Prometheus metrics path.
    implementation("io.micrometer:micrometer-tracing-bridge-otel")
    implementation("io.opentelemetry:opentelemetry-exporter-otlp")
    implementation("org.springframework.boot:spring-boot-starter-cache")
    implementation("org.springframework.boot:spring-boot-starter-thymeleaf")
    implementation("org.thymeleaf.extras:thymeleaf-extras-springsecurity6")
    implementation("nz.net.ultraq.thymeleaf:thymeleaf-layout-dialect:3.3.0")
    // SMTP via Jakarta Mail — see EmailService. We pull the mail starter
    // for the Jakarta Mail transitive dep but don't use Spring's
    // JavaMailSender bean (SMTP config lives in nexa_config and must be
    // editable at runtime, not properties-driven).
    implementation("org.springframework.boot:spring-boot-starter-mail")

    // WebJars (frontend libs) — bundled in the jar so the app works on
    // air-gapped (offline) networks without reaching any public CDN.
    // NOTE: webjar coordinates were chosen for offline availability via
    // Maven Central. `org.webjars.npm` is preferred for libs published as
    // node packages; classic `org.webjars` is used when only that variant
    // ships a usable browser bundle.
    //
    // The locator lets pages ask for `/webjars/<lib>/<file>` and leaves the
    // version to whatever is on the classpath. Without it every `<script>` and
    // `<link>` had to repeat the version, and a version bump here broke the
    // page silently — the browser 404s and says nothing the server can see.
    // Spring Boot turns on the resource chain as soon as it finds
    // `org.webjars.WebJarVersionLocator`, so adding the dependency is all of it.
    implementation("org.webjars:webjars-locator-lite")   // 버전은 Spring Boot BOM 이 고른다

    implementation("org.webjars:bootstrap:5.3.3")
    implementation("org.webjars:font-awesome:6.5.1")
    implementation("org.webjars.npm:htmx.org:2.0.4")
    implementation("org.webjars:jquery:4.0.0")
    // jQuery 4 가 없앤 이름들을 되살린다. jqWidgets 23.1.0 이 jQuery.isFunction,
    // isArray, trim, type, camelCase, nodeName, isWindow, isNumeric, parseJSON,
    // now, unique 를 번들 안에서 부르는데, 그 번들은 webjar 로 더 새 판이 없다.
    // migrate 없이 올리면 jqx-all.js 가 첫 줄에서 죽고 화면의 모든 그리드가
    // 사라진다(브라우저로 확인함). jQuery 팀이 바로 이 경우를 위해 내놓은
    // 공식 호환 계층이다.
    implementation("org.webjars.npm:jquery-migrate:4.0.2")
    // 23.1.0 이 webjar 로 나온 마지막 판이다(maven-metadata 의 <latest>, 2025-08).
    // npm 의 jqwidgets-scripts 는 26.0.0 까지 있지만 webjar 이 없고 상용
    // 라이선스이며, 26.0.0 도 jQuery 가 없앤 이름들(isFunction 123, trim 108,
    // isArray 67 …)을 그대로 부르므로 올려도 jquery-migrate 는 여전히 필요하다.
    implementation("org.webjars:jqwidgets:23.1.0")
    implementation("org.webjars.npm:codemirror:5.65.16")
    implementation("org.webjars.npm:signature_pad:4.2.0")
    implementation("org.webjars:qrcodejs:04f46c6")             // davidshimjs/qrcodejs — 이 좌표만 jar 안 폴더 이름과 버전이 같아 locator 가 찾는다
    implementation("org.webjars.npm:marked:12.0.2")
    implementation("org.webjars.npm:jsoneditor:10.1.2")       // josdejong/jsoneditor — tree+code+text JSON editor
    implementation("org.webjars.npm:echarts:5.5.1")           // charts (line/bar/pie/heatmap/gauge/sparkline)
    implementation("org.webjars.npm:leaflet:1.9.4")           // geo map atom — offline tile servers ok
    implementation("org.webjars.npm:jsbarcode:3.11.6")        // 1D barcode generation
    implementation("org.webjars.npm:rrule:2.7.2")             // RRULE / recurrence builder
    implementation("org.webjars.npm:zxcvbn:4.4.2")            // password strength scoring

    // Database Drivers (Multi-DB)
    runtimeOnly("com.mysql:mysql-connector-j")
    runtimeOnly("org.postgresql:postgresql")
    runtimeOnly("com.h2database:h2") // For development/testing

    // Liquibase for DB migration.
    // Boot 4 는 자동설정을 spring-boot-autoconfigure 에서 기술별 모듈로 쪼갰다.
    // liquibase-core 만 있으면 LiquibaseAutoConfiguration 이 없어 마이그레이션이
    // 아예 돌지 않고, 빈 데이터베이스 위에서 "Table not found" 로 뜬다.
    implementation("org.springframework.boot:spring-boot-liquibase")
    implementation("org.liquibase:liquibase-core")

    // Groovy support
    implementation("org.apache.groovy:groovy:4.0.24")
    implementation("org.apache.groovy:groovy-json:4.0.24")
    implementation("org.apache.groovy:groovy-sql:4.0.24")

    // Document processing
    implementation("org.apache.poi:poi:5.3.0")
    implementation("org.apache.poi:poi-ooxml:5.3.0")
    implementation("com.github.librepdf:openpdf:3.0.5")

    // API documentation
    implementation("org.springdoc:springdoc-openapi-starter-webmvc-ui:2.8.4")

    // Utilities
    implementation("com.google.guava:guava:33.7.1-jre")
    implementation("org.apache.commons:commons-lang3:3.20.0")
    implementation("commons-io:commons-io:2.18.0")

    // Lombok
    compileOnly("org.projectlombok:lombok")
    annotationProcessor("org.projectlombok:lombok")

    // Testing
    testImplementation("org.springframework.boot:spring-boot-starter-test")
    // Boot 4 는 MockMvc 테스트 자동설정을 web 모듈로 떼어 냈다.
    // org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc 가
    // org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc 로 옮겨졌고,
    // 그 클래스는 starter-test 가 아니라 여기에 있다.
    testImplementation("org.springframework.boot:spring-boot-starter-webmvc-test")
    // MockMvc 에 Spring Security 필터를 붙여 주는 자동설정도 따로 떨어졌다.
    // 이것이 없으면 @WithMockUser 가 걸린 요청이 그대로 401 로 돌아온다.
    testImplementation("org.springframework.boot:spring-boot-starter-security-test")
    testImplementation("org.springframework.security:spring-security-test")
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

tasks.withType<Test> {
    useJUnitPlatform()
    // The suite holds several Spring contexts at once (each @SpringBootTest
    // variant — MockMvc, extra properties, @DirtiesContext(AFTER_CLASS) — gets
    // its own) and was already close to the JVM's default heap; on Java 21 it
    // tipped over with an OutOfMemoryError while a context was being built.
    // WorkflowHttpActionTest used to rebuild its context after every method
    // and was the worst offender; that is gone, but the headroom stays so a
    // new test class doesn't reintroduce the OOM. Ask for the heap the suite
    // actually needs instead of leaving it to whatever quarter of the
    // machine's RAM the runner happens to give us.
    maxHeapSize = "2g"
}
plugins {
    // Toolchain auto-provisioning. build.gradle.kts pins the Java 21
    // toolchain, and without a download repository Gradle refuses to build
    // on any machine that lacks a JDK 21 ("Cannot find a Java installation
    // ... Toolchain download repositories have not been configured") — a
    // JRE-only host, or a laptop with only JDK 17, can't even run bootJar.
    // With the resolver Gradle fetches a matching JDK into
    // $GRADLE_USER_HOME/jdks once and reuses it. Where a JDK 21 is already
    // on the machine (setup-java in CI, the Temurin image in the Dockerfile)
    // nothing is downloaded.
    id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0"
}

