package com.nexabuilder.core.data;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.nexabuilder.core.code.Code;
import com.nexabuilder.core.code.CodeRepository;
import com.nexabuilder.core.entity.DynamicEntity;
import com.nexabuilder.core.entity.DynamicEntityRepository;
import com.nexabuilder.core.sql.SqlExecutor;
import com.nexabuilder.core.sql.SqlMetadata;
import com.nexabuilder.core.sql.SqlMetadataRepository;
import com.nexabuilder.core.sql.SqlPagination;
import com.nexabuilder.core.ui.NexaListDef;
import com.nexabuilder.core.ui.NexaListRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Server-side data adapter — provides jqxgrid-compatible paged/sorted/filtered
 * responses for grids and combos. Replaces the legacy egene
 * {@code /api/api_sql.jsp} + {@code /xefc/jsp/ui/bizajax/getListData.jsp} pair
 * with a single typed endpoint.
 *
 * <p>The shape of every response is {@code { "Rows": [...], "totalCount": N }}
 * which can be fed directly into {@code $.jqx.dataAdapter}.
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class DataAdapterService {

    private final NexaListRepository listRepository;
    private final DynamicEntityRepository entityRepository;
    private final SqlMetadataRepository sqlRepository;
    private final SqlExecutor sqlExecutor;
    private final SqlPagination sqlPagination;
    private final CodeRepository codeRepository;
    private final NamedParameterJdbcTemplate jdbcTemplate;
    private final ObjectMapper objectMapper;

    private static final int MAX_PAGE_SIZE = 1000;
    private static final Set<String> RESERVED_PARAMS = Set.of(
            "pagenum", "pagesize", "sortdatafield", "sortorder", "filterscount",
            "recordstartindex", "recordendindex");

    /**
     * Resolve a list definition and return paged data ready for jqxgrid.
     */
    @Transactional(readOnly = true)
    public Map<String, Object> queryList(String listId, Map<String, String> requestParams) {
        NexaListDef list = listRepository.findById(listId)
                .orElseThrow(() -> new IllegalArgumentException("List not found: " + listId));
        QueryRequest req = parse(requestParams, list.getPageSize());

        if (StringUtils.hasText(list.getSqlId())) {
            return executeSqlBacked(list.getSqlId(), req);
        }
        if (!StringUtils.hasText(list.getEntityId())) {
            throw new IllegalArgumentException(
                    "List " + listId + " has no sqlId nor entityId");
        }
        DynamicEntity entity = entityRepository.findById(list.getEntityId())
                .orElseThrow(() -> new IllegalArgumentException(
                        "Entity not found: " + list.getEntityId()));
        return executeEntityBacked(entity, req);
    }

    /**
     * Page data directly out of an entity table.
     */
    @Transactional(readOnly = true)
    public Map<String, Object> queryEntity(String entityId, Map<String, String> requestParams) {
        DynamicEntity entity = entityRepository.findById(entityId)
                .orElseThrow(() -> new IllegalArgumentException("Entity not found: " + entityId));
        QueryRequest req = parse(requestParams, 100);
        return executeEntityBacked(entity, req);
    }

    /**
     * Code-table data shaped for combo / tree adapters.
     * Returns {@code id}, {@code name}, {@code pid}, {@code value} fields.
     */
    @Transactional(readOnly = true)
    public Map<String, Object> queryCodes(String codeTypeId) {
        List<Code> codes = codeRepository.findByCodeTypeIdAndActiveTrueOrderBySortOrder(codeTypeId);
        List<Map<String, Object>> rows = new ArrayList<>(codes.size());
        for (Code c : codes) {
            Map<String, Object> row = new LinkedHashMap<>();
            row.put("id", firstNonBlank(c.getCodeValue(), c.getCodeId()));
            row.put("value", firstNonBlank(c.getCodeValue(), c.getCodeId()));
            row.put("name", firstNonBlank(c.getCodeName(), c.getCodeNameEn(), c.getCodeValue(), c.getCodeId()));
            row.put("pid", c.getParentCodeId());
            row.put("codeTypeId", c.getCodeTypeId());
            row.put("sortOrder", c.getSortOrder());
            rows.add(row);
        }
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("Rows", rows);
        result.put("totalCount", rows.size());
        return result;
    }

    /**
     * Field metadata for jqx {@code datafields}: returns {@code [{name, type}]}.
     */
    @Transactional(readOnly = true)
    public List<Map<String, Object>> entityDataFields(String entityId) {
        DynamicEntity entity = entityRepository.findById(entityId)
                .orElseThrow(() -> new IllegalArgumentException("Entity not found: " + entityId));
        List<Map<String, Object>> result = new ArrayList<>();
        try {
            String tableName = sanitize(entity.getTableName());
            // Probe column metadata via PreparedStatement metadata — works on every dialect.
            jdbcTemplate.getJdbcTemplate().execute(
                    "SELECT * FROM " + tableName + " WHERE 1=0",
                    (java.sql.PreparedStatement ps) -> {
                        var md = ps.getMetaData();
                        for (int i = 1; i <= md.getColumnCount(); i++) {
                            Map<String, Object> field = new LinkedHashMap<>();
                            field.put("name", md.getColumnLabel(i).toLowerCase(Locale.ROOT));
                            field.put("type", jdbcTypeToJqxType(md.getColumnType(i)));
                            result.add(field);
                        }
                        return null;
                    });
        } catch (Exception ignored) {
            // fall through with empty fields
        }
        return result;
    }

    // -------- implementation --------

    private Map<String, Object> executeSqlBacked(String sqlId, QueryRequest req) {
        SqlMetadata meta = sqlRepository.findById(sqlId)
                .orElseThrow(() -> new IllegalArgumentException("SQL not found: " + sqlId));
        Map<String, Object> params = new LinkedHashMap<>(req.filters);
        // Provide both case variants for legacy SQL definitions
        for (Map.Entry<String, Object> e : new ArrayList<>(params.entrySet())) {
            params.putIfAbsent(e.getKey().toLowerCase(Locale.ROOT), e.getValue());
            params.putIfAbsent(e.getKey().toUpperCase(Locale.ROOT), e.getValue());
        }
        var rs = sqlExecutor.executeQuery(meta.getSqlId(), params);
        List<Map<String, Object>> rows = rs.getRows();
        int total = rows.size();
        rows = applySort(rows, req);
        rows = applyPaging(rows, req);
        return wrap(rows, total);
    }

    private Map<String, Object> executeEntityBacked(DynamicEntity entity, QueryRequest req) {
        String table = sanitize(entity.getTableName());
        // Build WHERE
        StringBuilder where = new StringBuilder();
        MapSqlParameterSource params = new MapSqlParameterSource();
        int idx = 0;
        for (Map.Entry<String, Object> f : req.filters.entrySet()) {
            String column = sanitize(f.getKey());
            String key = "p" + (idx++);
            if (!where.isEmpty()) where.append(" AND ");
            // String search uses LIKE; everything else equality. Detect via value type.
            if (f.getValue() instanceof String s && (s.contains("%") || req.likeFilters.contains(f.getKey()))) {
                where.append("LOWER(").append(column).append(") LIKE LOWER(:")
                        .append(key).append(")");
                params.addValue(key, s.contains("%") ? s : "%" + s + "%");
            } else {
                where.append(column).append(" = :").append(key);
                params.addValue(key, f.getValue());
            }
        }
        // Count
        StringBuilder countSql = new StringBuilder("SELECT COUNT(*) FROM ").append(table);
        if (!where.isEmpty()) countSql.append(" WHERE ").append(where);
        Long total = jdbcTemplate.queryForObject(countSql.toString(), params, Long.class);
        if (total == null) total = 0L;

        // Rows
        StringBuilder rowsSql = new StringBuilder("SELECT * FROM ").append(table);
        if (!where.isEmpty()) rowsSql.append(" WHERE ").append(where);
        if (StringUtils.hasText(req.sortField)) {
            rowsSql.append(" ORDER BY ").append(sanitize(req.sortField)).append(
                    "desc".equalsIgnoreCase(req.sortOrder) ? " DESC" : " ASC");
        }
        rowsSql = new StringBuilder(sqlPagination.limitOffset(rowsSql.toString(), ":__limit", ":__offset"));
        params.addValue("__limit", req.pageSize);
        params.addValue("__offset", req.pageNum * req.pageSize);

        List<Map<String, Object>> rows = jdbcTemplate.queryForList(rowsSql.toString(), params);
        rows = lowerCaseKeys(rows);
        return wrap(rows, total.intValue());
    }

    private List<Map<String, Object>> applySort(List<Map<String, Object>> rows, QueryRequest req) {
        if (!StringUtils.hasText(req.sortField) || rows.isEmpty()) return rows;
        String field = req.sortField;
        int direction = "desc".equalsIgnoreCase(req.sortOrder) ? -1 : 1;
        rows.sort((a, b) -> {
            Object av = a.get(field);
            Object bv = b.get(field);
            if (av == null && bv == null) return 0;
            if (av == null) return -direction;
            if (bv == null) return direction;
            if (av instanceof Comparable && bv.getClass() == av.getClass()) {
                @SuppressWarnings({"unchecked", "rawtypes"})
                int cmp = ((Comparable) av).compareTo(bv);
                return cmp * direction;
            }
            return av.toString().compareTo(bv.toString()) * direction;
        });
        return rows;
    }

    private List<Map<String, Object>> applyPaging(List<Map<String, Object>> rows, QueryRequest req) {
        if (req.pageSize <= 0) return rows;
        int from = Math.min(req.pageNum * req.pageSize, rows.size());
        int to = Math.min(from + req.pageSize, rows.size());
        return new ArrayList<>(rows.subList(from, to));
    }

    private Map<String, Object> wrap(List<Map<String, Object>> rows, int total) {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("Rows", rows);
        result.put("totalCount", total);
        return result;
    }

    private List<Map<String, Object>> lowerCaseKeys(List<Map<String, Object>> rows) {
        List<Map<String, Object>> out = new ArrayList<>(rows.size());
        for (Map<String, Object> r : rows) {
            Map<String, Object> low = new LinkedHashMap<>();
            r.forEach((k, v) -> low.put(k == null ? null : k.toLowerCase(Locale.ROOT), v));
            out.add(low);
        }
        return out;
    }

    private QueryRequest parse(Map<String, String> params, int defaultPageSize) {
        QueryRequest q = new QueryRequest();
        q.pageNum = intOr(params.get("pagenum"), 0);
        q.pageSize = Math.min(intOr(params.get("pagesize"), defaultPageSize > 0 ? defaultPageSize : 100),
                MAX_PAGE_SIZE);
        q.sortField = params.get("sortdatafield");
        q.sortOrder = params.get("sortorder");

        int filterCount = intOr(params.get("filterscount"), 0);
        for (int i = 0; i < filterCount; i++) {
            String field = params.get("filterdatafield" + i);
            String value = params.get("filtervalue" + i);
            String condition = params.get("filtercondition" + i);
            if (!StringUtils.hasText(field) || !StringUtils.hasText(value)) continue;
            q.filters.put(field, value);
            if (condition != null && (condition.toLowerCase(Locale.ROOT).contains("contain")
                    || condition.toLowerCase(Locale.ROOT).contains("starts")
                    || condition.toLowerCase(Locale.ROOT).contains("ends"))) {
                q.likeFilters.add(field);
            }
        }
        // Pass-through filters: s_* convention from egene, plus any non-reserved
        // parameters that look like a column name.
        for (Map.Entry<String, String> e : params.entrySet()) {
            String k = e.getKey();
            if (RESERVED_PARAMS.contains(k.toLowerCase(Locale.ROOT))) continue;
            if (k.startsWith("filter")) continue;
            if (!StringUtils.hasText(e.getValue())) continue;
            String norm = k.startsWith("s_") ? k.substring(2) : k;
            if (!norm.matches("[A-Za-z_][A-Za-z0-9_]*")) continue;
            q.filters.putIfAbsent(norm, e.getValue());
        }
        return q;
    }

    private int intOr(String s, int fallback) {
        try { return s == null ? fallback : Integer.parseInt(s); }
        catch (NumberFormatException e) { return fallback; }
    }

    private String firstNonBlank(String... values) {
        for (String v : values) if (StringUtils.hasText(v)) return v;
        return "";
    }

    private String sanitize(String identifier) {
        if (identifier == null) throw new IllegalArgumentException("Identifier cannot be null");
        if (!identifier.matches("^[a-zA-Z_][a-zA-Z0-9_]*$")) {
            throw new IllegalArgumentException("Invalid identifier: " + identifier);
        }
        return identifier;
    }

    private String jdbcTypeToJqxType(int sqlType) {
        return switch (sqlType) {
            case java.sql.Types.BIT, java.sql.Types.BOOLEAN -> "bool";
            case java.sql.Types.TINYINT, java.sql.Types.SMALLINT, java.sql.Types.INTEGER,
                 java.sql.Types.BIGINT -> "int";
            case java.sql.Types.FLOAT, java.sql.Types.REAL, java.sql.Types.DOUBLE,
                 java.sql.Types.NUMERIC, java.sql.Types.DECIMAL -> "number";
            case java.sql.Types.DATE, java.sql.Types.TIME, java.sql.Types.TIMESTAMP,
                 java.sql.Types.TIMESTAMP_WITH_TIMEZONE -> "date";
            default -> "string";
        };
    }

    /** Parsed query request used internally. */
    private static class QueryRequest {
        int pageNum;
        int pageSize;
        String sortField;
        String sortOrder;
        final Map<String, Object> filters = new LinkedHashMap<>();
        final Set<String> likeFilters = new java.util.HashSet<>();
    }
}
package com.nexabuilder.api.controller;

import com.nexabuilder.api.dto.ApiResponse;
import com.nexabuilder.core.data.DataAdapterService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

/**
 * Server-side data adapter endpoints — jqxgrid-compatible.
 *
 * <p>All endpoints return {@code { "Rows": [...], "totalCount": N }} so the
 * frontend can feed them straight into {@code $.jqx.dataAdapter}. Responses are
 * <em>not</em> wrapped with {@link ApiResponse} for the paged endpoints — the
 * envelope would force the adapter to unwrap before consumption. For status
 * checks / non-paged endpoints we still use the envelope.
 *
 * <p>Standard jqxgrid query params:
 * <ul>
 *   <li>{@code pagenum} / {@code pagesize}</li>
 *   <li>{@code sortdatafield} / {@code sortorder}</li>
 *   <li>{@code filterscount} + {@code filterdatafield{N}}, {@code filtervalue{N}},
 *       {@code filtercondition{N}}</li>
 * </ul>
 * <p>Plus egene-compatible {@code s_*} filters and any column-named param are
 * accepted as equality filters.
 */
@RestController
@RequestMapping("/api/v1/data")
@RequiredArgsConstructor
public class DataAdapterController {

    private final DataAdapterService service;

    @GetMapping("/lists/{listId}")
    public Map<String, Object> listData(@PathVariable String listId,
                                        @RequestParam Map<String, String> params) {
        return service.queryList(listId, params);
    }

    @GetMapping("/entity/{entityId}")
    public Map<String, Object> entityData(@PathVariable String entityId,
                                          @RequestParam Map<String, String> params) {
        return service.queryEntity(entityId, params);
    }

    @GetMapping("/codes/{codeTypeId}")
    public Map<String, Object> codeData(@PathVariable String codeTypeId) {
        return service.queryCodes(codeTypeId);
    }

    @GetMapping("/entity/{entityId}/datafields")
    public ResponseEntity<ApiResponse<List<Map<String, Object>>>> dataFields(@PathVariable String entityId) {
        return ResponseEntity.ok(ApiResponse.ok(service.entityDataFields(entityId)));
    }
}
package com.nexabuilder.api;

import com.fasterxml.jackson.databind.ObjectMapper;
