import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import static org.hamcrest.Matchers.is;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * Pins the soft-delete rule for {@code POST /api/v1/builder/lists/{listId}/data}
 * (the row feed behind the runtime kanban / tree / calendar / pivot / gantt /
 * map / chart views and the export endpoints).
 *
 * <p>{@code GET /api/v1/builder/lists/{id}} and {@code /app/list/<id>} already
 * refuse a list whose {@code deleted_at} is set (migration 027), and the
 * export URLs were aligned on 2026-09-19. The data endpoint must give the
 * same verdict — otherwise a caller that skips the definition call keeps
 * reading rows of a list the operator put in the trash.
 *
 * <p>Same fixture shape as {@link ListExportIntegrationTest}: random 8-char
 * suffix, no cleanup.
 */
@SpringBootTest
@AutoConfigureMockMvc
@WithMockUser(username = "admin", roles = {"ADMIN"})
class BuilderListDataSoftDeleteIntegrationTest {

    @Autowired private MockMvc mockMvc;
    @Autowired private ObjectMapper objectMapper;
    @Autowired private DynamicEntityRepository entityRepository;
    @Autowired private NexaListRepository listRepository;
    @Autowired private EntityService entityService;
    @Autowired private SchemaDdlService schemaDdlService;

    private String seedList() throws Exception {
        String sfx = UUID.randomUUID().toString().replace("-", "").substring(0, 8);
        String entityId = "ldata_" + sfx;
        String tableName = "t_ldata_" + sfx;
        String listId = "list_ldata_" + sfx;

        List<Map<String, Object>> fields = List.of(
                Map.of("name", "name", "label", "Name", "type", "string")
        );
        DynamicEntity entity = DynamicEntity.builder()
                .entityId(entityId)
                .entityName("ListData " + sfx)
                .tableName(tableName)
                .keyColumn("id")
                .description("list data fixture")
                .fieldsJson(objectMapper.writeValueAsString(fields))
                .active(true)
                .system(false)
                .regDttm(LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss")))
                .build();
        entity = entityRepository.save(entity);
        schemaDdlService.ensureTable(entity);

        Map<String, Object> row = new LinkedHashMap<>();
        row.put("id", "r_" + sfx);
        row.put("name", "row " + sfx);
        entityService.insert(tableName, row);

        List<Map<String, Object>> cols = List.of(
                Map.of("field", "id", "label", "ID"),
                Map.of("field", "name", "label", "Name")
        );
        NexaListDef list = NexaListDef.builder()
                .listId(listId)
                .listName("ListData " + sfx)
                .entityId(entityId)
                .columnsJson(objectMapper.writeValueAsString(cols))
                .active(true)
                .build();
        listRepository.save(list);
        return listId;
    }

    private static String dataUrl(String listId) {
        return "/api/v1/builder/lists/" + listId + "/data";
    }

    @Test
    void liveListServesRows() throws Exception {
        String listId = seedList();

        mockMvc.perform(post(dataUrl(listId))
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.success", is(true)))
                .andExpect(jsonPath("$.totalCount", is(1)));
    }

    @Test
    void softDeletedListIsNotFoundForDataAndDefinition() throws Exception {
        String listId = seedList();

        // Same shape /admin/trash writes (yyyyMMddHHmmss string).
        NexaListDef list = listRepository.findById(listId).orElseThrow();
        list.setDeletedAt("20260920000000");
        listRepository.save(list);

        // The data feed must reach the same verdict as the definition call —
        // same exception type + message so GlobalExceptionHandler emits the
        // same 400 JSON for both.
        mockMvc.perform(post(dataUrl(listId))
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_JSON))
                .andExpect(jsonPath("$.success", is(false)))
                .andExpect(jsonPath("$.message", is("List not found: " + listId)));

        mockMvc.perform(get("/api/v1/builder/lists/" + listId))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.success", is(false)))
                .andExpect(jsonPath("$.message", is("List not found: " + listId)));
    }
}
# NexaBuilder CI (#55)
#
# Runs on every push to master and every pull-request. Verifies:
#   - the full test suite passes
#   - the production fat-jar still builds
#
# We run on ubuntu-latest with Java 21 (the toolchain the project
# pins). Gradle's local cache is restored between runs so the build
# stays fast.

name: ci

on:
  push:
    branches: [ master ]
  pull_request:
    branches: [ master ]

# Cancel an in-flight run for the same branch when a new commit lands —
# don't waste minutes building obsolete code.
concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  test:
    name: test + bootJar
    runs-on: ubuntu-latest
    timeout-minutes: 25

    steps:
      - name: Checkout
        uses: actions/checkout@v6

      - name: Set up Java 21 (Temurin)
        uses: actions/setup-java@v5
        with:
          distribution: temurin
          java-version: 21
          cache: gradle

      - name: Make gradlew executable
        run: chmod +x ./gradlew

      - name: Run unit + integration tests
        run: ./gradlew --no-daemon test

      - name: Build production jar
        run: ./gradlew --no-daemon bootJar -x test

      - name: Upload test reports on failure
        if: failure()
        uses: actions/upload-artifact@v7
        with:
          name: test-reports
          path: |
            build/reports/tests/test/
            build/test-results/test/
          retention-days: 7

      - name: Upload jar
        if: success() && github.ref == 'refs/heads/master'
        uses: actions/upload-artifact@v7
        with:
          name: nexabuilder-jar
          path: build/libs/nexabuilder-*.jar
          retention-days: 14
# CodeQL static analysis (#58)
#
# GitHub-native security scanner. Runs on every push to master, every
# PR targeting master, and on a weekly schedule so newly-published
# CVE rules also catch issues in code that hasn't been touched.

name: codeql

on:
  push:
    branches: [ master ]
  pull_request:
    branches: [ master ]
  schedule:
    # Mondays at 04:00 UTC (= 13:00 KST). Picked off-peak so security
    # alerts land before the working week starts.
    - cron: "0 4 * * 1"

# Tied to ref so a follow-up commit aborts the obsolete run.
concurrency:
  group: codeql-${{ github.ref }}
  cancel-in-progress: true

jobs:
  analyze:
    name: analyze (java)
    runs-on: ubuntu-latest
    timeout-minutes: 40

    # Uploading SARIF needs code scanning, which a private repository only has
    # with GitHub Advanced Security. Without it every run built fine and then
    # failed on the upload, so each pull request carried a red check that said
    # nothing about the change. Skip the job while the repository is private;
    # it starts working again by itself if the repository is made public.
    if: github.event.repository.visibility == 'public'

    permissions:
      # Needed to upload SARIF results to the Security tab.
      security-events: write
      actions: read
      contents: read

    steps:
      - name: Checkout
        uses: actions/checkout@v6

      - name: Set up Java 21 (Temurin)
        uses: actions/setup-java@v5
        with:
          distribution: temurin
          java-version: 21
          cache: gradle

      - name: Initialize CodeQL
        uses: github/codeql-action/init@v3
        with:
          languages: java
          # Default + security-extended catches a wider set of CWEs at
          # the cost of a longer scan. Acceptable for a weekly run.
          queries: +security-extended

      - name: Build (CodeQL needs a real compile pass)
        run: |
          chmod +x ./gradlew
          ./gradlew --no-daemon compileJava -x test

      - name: Perform CodeQL analysis
        uses: github/codeql-action/analyze@v3
        with:
          category: "/language:java"
# Docker image publishing to GHCR (#65)
#
# Companion to the tag-triggered release workflow (#59). When a
# `v*.*.*` tag is pushed:
#   1. Builds the multi-stage Dockerfile from this repo.
#   2. Pushes the image to GitHub Container Registry
#      (ghcr.io/<owner>/nexabuilder) under three tags:
#         - <full-version>   (e.g. 1.5.0)
#         - <major.minor>    (e.g. 1.5)
#         - latest           (only for non-prerelease tags)
#
# Image inherits the auto-built version label from build/Dockerfile;
# K8s manifests in deploy/k8s/ reference `:1.5.0` etc, so just
# bumping the tag is enough to roll forward.

name: docker-publish

on:
  push:
    tags:
      - "v*.*.*"

concurrency:
  group: docker-publish-${{ github.ref }}
  cancel-in-progress: false

jobs:
  build-and-push:
    name: build + push ghcr
    runs-on: ubuntu-latest
    timeout-minutes: 40

    permissions:
      # Needed to push packages to GHCR under the repo owner.
      contents: read
      packages: write

    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@v3

      - name: Log in to GHCR
        uses: docker/login-action@v3
        with:
          registry: ghcr.io
          username: ${{ github.actor }}
          password: ${{ secrets.GITHUB_TOKEN }}

      - name: Derive image tags
        id: meta
        uses: docker/metadata-action@v5
        with:
          # Lowercase repo name → ghcr.io expects lowercase paths.
          images: ghcr.io/${{ github.repository_owner }}/nexabuilder
          # SemVer parsing of the v-prefixed tag.
          tags: |
            type=semver,pattern={{version}}
            type=semver,pattern={{major}}.{{minor}}
            type=raw,value=latest,enable=${{ !contains(github.ref, '-') }}

      - name: Build and push
        uses: docker/build-push-action@v6
        with:
          context: .
          push: true
          tags: ${{ steps.meta.outputs.tags }}
          labels: ${{ steps.meta.outputs.labels }}
          # Layer-cache between runs so a re-release rebuilds in
          # ~30s instead of ~5min.
          cache-from: type=gha
          cache-to: type=gha,mode=max
# Tag-triggered release automation (#59)
#
# When a `v*.*.*` tag is pushed (e.g. `git tag v1.5.0 && git push
# origin v1.5.0`), this workflow:
#   1. Builds the production fat jar.
#   2. Creates a GitHub Release for the tag with the jar attached.
#
# Release notes are auto-generated from the commit history between
# this tag and the previous one (`generate_release_notes: true`).
# For hand-curated notes, edit the release after creation.

name: release

on:
  push:
    tags:
      - "v*.*.*"

# Single in-flight release at a time keeps the artifact naming sane.
concurrency:
  group: release-${{ github.ref }}
  cancel-in-progress: false

jobs:
  publish:
    name: build + release
    runs-on: ubuntu-latest
    timeout-minutes: 30

    permissions:
      # softprops/action-gh-release needs contents:write to create
      # the release object and upload assets.
      contents: write

    steps:
      - name: Checkout
        uses: actions/checkout@v6
        with:
          # Need full history so release-notes generation can diff
          # against the previous tag.
          fetch-depth: 0

      - name: Set up Java 21 (Temurin)
        uses: actions/setup-java@v5
        with:
          distribution: temurin
          java-version: 21
          cache: gradle

      - name: Build production jar
        run: |
          chmod +x ./gradlew
          ./gradlew --no-daemon bootJar -x test

      - name: List artifacts
        run: ls -la build/libs/

      - name: Create GitHub Release
        uses: softprops/action-gh-release@v2
        with:
          # The tag name is the release name by default.
          generate_release_notes: true
          # Mark prereleases for any tag with a hyphen suffix
          # (v1.5.0-rc1, v2.0.0-beta) so the latest-stable badge
          # isn't accidentally hijacked.
          prerelease: ${{ contains(github.ref, '-') }}
          files: |
            build/libs/nexabuilder-*.jar

