    /**
     * Single "is this list alive?" verdict for every runtime caller —
     * {@link #listDefinition}, {@link #listData} and the export endpoints.
     *
     * <p>Soft-deleted lists (see migration 027) should look "gone" to
     * runtime callers — surface as 404-ish so direct /app/list/<id>
     * bookmarks fail loudly instead of serving a stale row. Missing and
     * trashed lists throw the identical exception on purpose: the
     * runtime page and {@code GlobalExceptionHandler} (400 JSON) key on
     * the type and the {@code "List not found: …"} text, and a caller
     * must not be able to tell the two cases apart.
     */
    public NexaListDef requireLiveList(String listId) {
        NexaListDef list = listRepository.findById(listId)
                .orElseThrow(() -> new IllegalArgumentException("List not found: " + listId));
        if (list.getDeletedAt() != null) {
            throw new IllegalArgumentException("List not found: " + listId);
        }
        return list;
    }

    public Map<String, Object> listDefinition(String listId) {
        NexaListDef list = requireLiveList(listId);
        DynamicEntity entity = entity(list.getEntityId());
        // Map.ofEntries (not Map.of) since we're now past the 10-entry limit
        // — Pivot view (migration 057) pushed us to 11.
        return Map.ofEntries(
                Map.entry("list", list),
                Map.entry("entity", entityMap(entity)),
                Map.entry("columns", jsonList(list.getColumnsJson())),
                Map.entry("filters", jsonList(list.getFiltersJson())),
                Map.entry("actions", jsonMap(list.getActionsJson())),
                // Conditional row styling — empty list when none configured
                // so the runtime grid doesn't have to null-check.
                Map.entry("rowStyleRules", jsonList(list.getRowStyleRules())),
                // Kanban view (046) — empty map hides the "Kanban 보기" toggle.
                Map.entry("kanban", jsonMap(list.getKanbanConfig())),
                // Calendar view (049) — analogous flag.
                Map.entry("calendar", jsonMap(list.getCalendarConfig())),
                // Tree view (052) — analogous flag.
                Map.entry("tree", jsonMap(list.getTreeConfig())),
                // Map view (056) — analogous flag.
                Map.entry("map", jsonMap(list.getMapConfig())),
                // Pivot view (057) — analogous flag; empty map hides the
                // "Pivot 보기" toggle on the runtime list.
                Map.entry("pivot", jsonMap(list.getPivotConfig())),
                // Gantt view (058) — analogous flag.
                Map.entry("gantt", jsonMap(list.getGanttConfig())),
                // Chart view (059) — analogous flag.
                Map.entry("chart", jsonMap(list.getChartConfig()))
        );
    }

    @Transactional(readOnly = true)
    public RecordSet listData(String listId, Map<String, Object> params) {
        // Same gate as listDefinition — the runtime views fetch the
        // definition first, but /api/v1/builder/lists/{id}/data is reachable
        // on its own and must not hand out rows of a trashed list.
        NexaListDef list = requireLiveList(listId);
        if (StringUtils.hasText(list.getSqlId())) {
            return sqlExecutor.executeQuery(list.getSqlId(), params == null ? Map.of() : params);
        }
        DynamicEntity entity = entity(list.getEntityId());
        return entityService.list(entity.getTableName(), params, 0, list.getPageSize() == null ? 100 : list.getPageSize());
    }

    public Map<String, Object> formDefinition(String formId) {
        return formDefinition(formId, false);
    }

    /**
     * @param includeInactive when true, returns all atoms (active+inactive) so the
     *                        designer can edit fields that were toggled off. The
     *                        runtime always passes false to render only live fields.
     */
    public Map<String, Object> formDefinition(String formId, boolean includeInactive) {
        NexaFormDef form = formRepository.findById(formId)
                .orElseThrow(() -> new IllegalArgumentException("Form not found: " + formId));
        // Mirror listDefinition — soft-deleted forms surface as 404-ish.
        // The designer path uses a separate /api/v1/admin/forms endpoint,
        // so this only affects the runtime /app/form/<id> entry.
        if (!includeInactive && form.getDeletedAt() != null) {
            throw new IllegalArgumentException("Form not found: " + formId);
        }
        DynamicEntity entity = entity(form.getEntityId());
        List<NexaAtomDef> rows = includeInactive
                ? atomRepository.findByFormIdOrderBySortOrderAsc(formId)
                : atomRepository.findByFormIdAndActiveTrueOrderBySortOrderAsc(formId);

        // Field-level perms — drop hidden atoms and stamp readonly=true
        // on restricted ones BEFORE the response leaves the server, so
        // the runtime never gets to see the bytes for a role-hidden
        // field. Designer paths skip this filter (includeInactive=true
        // means we're rendering the editor canvas).
        String roleId = includeInactive ? null : currentRoleId();
        List<Map<String, Object>> atoms = rows.stream()
                .map(this::atomMap)
                .map(m -> applyFieldPerm(m, roleId))
                .filter(java.util.Objects::nonNull)
                .toList();
        return Map.of(
                "form", form,
                "entity", entityMap(entity),
                "layout", jsonMap(form.getLayoutJson()),
                "actions", jsonMap(form.getActionsJson()),
                "atoms", atoms
        );
    }

    /**
     * Apply atom.rolePermJson against the current user's role. ADMIN
     * bypasses everything; designer/editor views pass {@code null} as
     * the role so they always see every atom regardless of perms.
     *
     * @return the (possibly mutated) atom map, or {@code null} when the
     *         atom should be hidden from this user
     */
    @SuppressWarnings("unchecked")
    private Map<String, Object> applyFieldPerm(Map<String, Object> atom, String roleId) {
        if (roleId == null || "ADMIN".equals(roleId)) return atom;
        Object rp = atom.get("rolePerm");
        if (!(rp instanceof Map<?, ?> rule) || rule.isEmpty()) return atom;
        Object hideFor = ((Map<String, Object>) rule).get("hideFor");
        if (hideFor instanceof List<?> hidden && hidden.contains(roleId)) {
            return null;     // filter the atom out entirely
        }
        Object readonlyFor = ((Map<String, Object>) rule).get("readonlyFor");
        if (readonlyFor instanceof List<?> ro && ro.contains(roleId)) {
            // Build a defensive copy so we don't mutate the cached map.
            Map<String, Object> copy = new LinkedHashMap<>(atom);
            copy.put("readonly", true);
            return copy;
        }
        return atom;
    }

    /**
     * Resolve the role-id of the user driving the current HTTP request.
     * Reads the session attribute that {@code SecurityConfig.successHandler}
     * stores after form login. Returns {@code null} when no session user
     * is available (background jobs, integration tests, the designer
     * path where field-level perms shouldn't apply anyway).
     */
    private String currentRoleId() {
        try {
            var attrs = org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
            if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes sra)) return null;
            var session = sra.getRequest().getSession(false);
            if (session == null) return null;
            Object user = session.getAttribute("nexabuilder.user");
            if (!(user instanceof com.nexabuilder.core.user.User u)) return null;
            if (Boolean.TRUE.equals(u.getAdmin())) return "ADMIN";
            return u.getRoleId();
        } catch (Exception ignored) {
            return null;
        }
    }

