@SpringBootTest
@AutoConfigureMockMvc
@WithMockUser(username = "admin", roles = {"ADMIN"})
class DataAdapterIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Test
    void entityDataReturnsJqxgridShape() throws Exception {
        mockMvc.perform(get("/api/v1/data/entity/USER")
                        .param("pagenum", "0")
                        .param("pagesize", "10"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.Rows", notNullValue()))
                .andExpect(jsonPath("$.totalCount", greaterThanOrEqualTo(1)));
    }

    @Test
    void entityDataAppliesEqualityFilter() throws Exception {
