                        .param("pagenum", "0")
                        .param("pagesize", "10"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount", is(1)))
                .andExpect(jsonPath("$.Rows[0].user_id", is("admin")));
    }

    @Test
    void entityDataAppliesJqxgridFilter() throws Exception {
        mockMvc.perform(get("/api/v1/data/entity/USER")
                        .param("filterscount", "1")
                        .param("filterdatafield0", "user_id")
                        .param("filtervalue0", "admin")
                        .param("filtercondition0", "CONTAINS")
                        .param("pagenum", "0")
                        .param("pagesize", "10"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount", greaterThanOrEqualTo(1)))
                .andExpect(jsonPath("$.Rows[0].user_id", is("admin")));
    }

    @Test
    void entityDataAppliesSort() throws Exception {
        mockMvc.perform(get("/api/v1/data/entity/USER")
                        .param("sortdatafield", "user_id")
                        .param("sortorder", "asc")
                        .param("pagenum", "0")
                        .param("pagesize", "20"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.Rows", notNullValue()));
