package com.nexabuilder.api.controller;

import com.nexabuilder.api.dto.ApiResponse;
import com.nexabuilder.core.sql.SqlExecutor;
import com.nexabuilder.infra.file.FileStorageService;
import com.nexabuilder.infra.security.AccessAuditHandler;
import com.nexabuilder.plugin.groovy.GroovyScriptService;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.servlet.NoHandlerFoundException;
import org.springframework.web.servlet.resource.NoResourceFoundException;

@RestControllerAdvice
@RequiredArgsConstructor
@Slf4j
public class GlobalExceptionHandler {

    private final AccessAuditHandler accessAuditHandler;

    /**
     * AccessDeniedException from any controller (e.g. our resource-level
     * gate in {@link com.nexabuilder.web.controller.RuntimeUiController})
     * gets handed back to {@link AccessAuditHandler} so the audit row is
     * still written and the user still sees the friendly /error/403 page.
     * Without this override, {@link #handleGeneral(Exception)} would
     * swallow it into a 500 because @RestControllerAdvice runs before
     * Spring Security's ExceptionTranslationFilter.
     */
    @ExceptionHandler(AccessDeniedException.class)
    public void handleAccessDenied(AccessDeniedException ex,
                                   HttpServletRequest request,
                                   HttpServletResponse response) throws Exception {
        accessAuditHandler.handle(request, response, ex);
    }

    /** #52 — quota-exceeded throws return HTTP 429 with the policy message. */
    @ExceptionHandler(com.nexabuilder.core.ai.AiQuotaService.QuotaExceededException.class)
    public ResponseEntity<ApiResponse<Void>> handleAiQuota(
            com.nexabuilder.core.ai.AiQuotaService.QuotaExceededException ex) {
        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
                .body(ApiResponse.error(ex.getMessage()));
    }

    /** #113 — cost-cap exceeded returns HTTP 429 just like the
     *  call-count quota so client code can treat them uniformly. */
    @ExceptionHandler(com.nexabuilder.core.ai.AiCostQuotaService.CostQuotaExceededException.class)
    public ResponseEntity<ApiResponse<Void>> handleAiCostQuota(
            com.nexabuilder.core.ai.AiCostQuotaService.CostQuotaExceededException ex) {
        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
                .body(ApiResponse.error(ex.getMessage()));
    }

    /** #70 — PII-guard block returns HTTP 400 with the violation message. */
    @ExceptionHandler(com.nexabuilder.core.ai.AiPiiGuard.PiiViolationException.class)
    public ResponseEntity<ApiResponse<Void>> handleAiPii(
            com.nexabuilder.core.ai.AiPiiGuard.PiiViolationException ex) {
        return ResponseEntity.badRequest().body(ApiResponse.error(ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ApiResponse<Void>> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .map(e -> e.getField() + ": " + e.getDefaultMessage())
                .reduce((a, b) -> a + "; " + b)
                .orElse("Validation failed");
        return ResponseEntity.badRequest().body(ApiResponse.error(message));
    }

    @ExceptionHandler(SqlExecutor.SqlNotFoundException.class)
    public ResponseEntity<ApiResponse<Void>> handleSqlNotFound(SqlExecutor.SqlNotFoundException ex) {
        return ResponseEntity.badRequest().body(ApiResponse.error(ex.getMessage()));
    }

    @ExceptionHandler(FileStorageService.FileStorageException.class)
    public ResponseEntity<ApiResponse<Void>> handleFileStorage(FileStorageService.FileStorageException ex) {
        return ResponseEntity.badRequest().body(ApiResponse.error(ex.getMessage()));
    }

    @ExceptionHandler(GroovyScriptService.GroovyExecutionException.class)
    public ResponseEntity<ApiResponse<Void>> handleGroovyError(GroovyScriptService.GroovyExecutionException ex) {
        return ResponseEntity.badRequest().body(ApiResponse.error(ex.getMessage()));
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<ApiResponse<Void>> handleIllegalArgument(IllegalArgumentException ex) {
        return ResponseEntity.badRequest().body(ApiResponse.error(ex.getMessage()));
    }

    /**
     * 404 for static resources — must NOT return JSON. When the browser
     * fetches /webjars/jquery/jquery.min.js with <script>, a JSON 500
     * response is interpreted as JavaScript → SyntaxError, which then
     * cascades through every downstream script (jqWidgets, CodeMirror, etc.)
     * and ultimately crashes the renderer with STATUS_BREAKPOINT under heavy
     * pressure. We return a plain 404 with an empty body so the browser
     * surfaces the missing-file the right way.
     *
     * Both exception types are handled because Spring 6.1 introduced
     * NoResourceFoundException; pre-6.1 deployments throw NoHandlerFoundException.
     */
    @ExceptionHandler({NoResourceFoundException.class, NoHandlerFoundException.class})
    public ResponseEntity<Void> handleNoResource(Exception ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).build();
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ApiResponse<Void>> handleGeneral(Exception ex) {
        log.error("Unexpected error", ex);
        return ResponseEntity.internalServerError()
                .body(ApiResponse.error("Internal server error"));
    }
}
/**
 * Nexa.Data — server-aware DataSource / DataAdapter factory.
 *
 * Ported from the egene52 pattern around $.jqx.dataAdapter:
 *   var source = {datatype, datafields, url, root, type, pagesize, beforeprocessing, ...};
 *   var adapter = new $.jqx.dataAdapter(source, {formatData, ...});
 *   grid.jqxGrid({ source: adapter, ... });
 *
 * Adds:
 *   - Server-side paged endpoints (`/api/v1/data/lists/{id}`, `/api/v1/data/entity/{id}`).
 *   - Auto-detection of the response envelope: works with {Rows, totalCount}
 *     as well as legacy {data, totalCount} and plain arrays.
 *   - Cached code-table adapters (Nexa.Data.codes('USER_LANG')).
 *   - Tree helper using getRecordsHierarchy.
 *   - Local data shortcut.
 *
 * Usage:
 *   const adapter = Nexa.Data.adapter({ kind: 'list', listId: 'user-list', pageSize: 50 },
 *                                     { autoBind: true });
 *   $('#grid').jqxGrid({ source: adapter, columns: [...], pageable: true, virtualmode: true,
 *                       rendergridrows: args => args.data });
 */
(function (global) {
    if (!global.Nexa) global.Nexa = {};
    const Nexa = global.Nexa;
    if (Nexa.Data) return; // do not redefine

    const codeCache = new Map(); // codeTypeId -> Promise<adapter>
    const entityFieldsCache = new Map();

    // ---------- defaults & helpers ----------
    function isPlainObject(value) {
        return value != null && Object.prototype.toString.call(value) === '[object Object]';
    }

    function jqxAvailable() {
        return typeof window.$ !== 'undefined' && window.$.jqx && window.$.jqx.dataAdapter;
    }

    function requireJqx() {
        if (!jqxAvailable()) {
            throw new Error('Nexa.Data requires jQuery + jqWidgets to be loaded.');
        }
    }

    /** Build the URL that the adapter should call for a given spec. */
    function urlFor(spec) {
        switch (spec.kind) {
            case 'list':   return '/api/v1/data/lists/' + encodeURIComponent(spec.listId);
            case 'entity': return '/api/v1/data/entity/' + encodeURIComponent(spec.entityId);
            case 'codes':  return '/api/v1/data/codes/' + encodeURIComponent(spec.codeTypeId);
            case 'rest':   return spec.url;
            default:       return spec.url; // local / custom
        }
    }

    /** Choose the response root key. Nexa adapter endpoints use "Rows". */
    function rootFor(spec) {
        if (spec.root) return spec.root;
        return spec.kind === 'rest' ? null : 'Rows';
    }

    /** Default datafields when spec doesn't supply any — falls back to whatever rows look like. */
    function defaultDatafields(spec) {
        if (Array.isArray(spec.fields)) return spec.fields;
        return null;
    }

    // ---------- source builder ----------
    /**
     * Normalize a spec into a jqxgrid-compatible source object.
     * Does NOT wrap with $.jqx.dataAdapter — use Nexa.Data.adapter() for that.
     */
    function source(spec) {
        if (Array.isArray(spec)) {
            // shortcut: array of rows → local datasource
            return { datatype: 'array', localdata: spec, datafields: [] };
        }
        spec = Object.assign({}, spec);
        const fields = defaultDatafields(spec) || [];

        if (spec.kind === 'local') {
            return {
                datatype: 'array',
                localdata: spec.rows || [],
                datafields: fields
            };
        }

        const url = urlFor(spec);
        const root = rootFor(spec);
        const src = {
            datatype: spec.datatype || 'json',
            datafields: fields,
            url: url,
            type: spec.method || 'GET',
            cache: spec.cache !== false,
            data: Object.assign({}, spec.params || {})
        };
        if (root) src.root = root;
        if (spec.pageSize) src.pagesize = spec.pageSize;
        if (spec.totalRecordsField !== false) {
            src.beforeprocessing = function (data) {
                if (data && typeof data.totalCount === 'number') {
                    src.totalrecords = data.totalCount;
                }
                if (typeof spec.beforeprocessing === 'function') {
                    spec.beforeprocessing(data);
                }
            };
        }
        if (spec.id) src.id = spec.id;
        if (spec.sortColumn) src.sortcolumn = spec.sortColumn;
        if (spec.sortDirection) src.sortdirection = spec.sortDirection;
        // Caller-supplied source overrides (e.g. updaterow for editable grids,
        // custom cache strategy, addrow/deleterow callbacks). Merged last so
        // they win over the defaults above.
        if (isPlainObject(spec.source)) Object.assign(src, spec.source);
        return src;
    }

    // ---------- adapter ----------
    /**
     * Build a $.jqx.dataAdapter from a Nexa spec.
     *
     * Spec recognized kinds: 'list' | 'entity' | 'codes' | 'rest' | 'local'.
     *
     * Options:
     *   autoBind:      bool (default false; jqxgrid binds lazily on its own)
     *   formatData:    fn(data, source) — extra request params (e.g. form conds)
