package com.nexabuilder.core.sql;

import jakarta.persistence.*;
import lombok.*;

/**
 * Represents a named SQL definition stored in the database.
 * Replaces the legacy ecr_sql table structure.
 *
 * The no-code platform stores all SQL queries as metadata,
 * allowing dynamic query execution by SQL_ID.
 */
@Entity
@Table(name = "nexa_sql")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class SqlMetadata {

    @Id
    @Column(name = "sql_id", length = 200)
    private String sqlId;

    @Column(name = "sql_name", length = 200)
    private String sqlName;

    @Column(name = "sql_desc", length = 500)
    private String description;

    /** Default SQL (database-agnostic or primary dialect) */
    @Column(name = "sql_text", columnDefinition = "TEXT")
    private String sqlText;

    /** MySQL-specific SQL variant */
    @Column(name = "sql_mysql", columnDefinition = "TEXT")
    private String sqlMysql;

    /** PostgreSQL-specific SQL variant */
    @Column(name = "sql_postgres", columnDefinition = "TEXT")
    private String sqlPostgres;

    /** Oracle-specific SQL variant */
    @Column(name = "sql_oracle", columnDefinition = "TEXT")
    private String sqlOracle;

    /** SQL type: SELECT, INSERT, UPDATE, DELETE, PROCEDURE */
    @Column(name = "sql_type", length = 20)
    private String sqlType;

    /** Associated entity ID for ORM binding */
    @Column(name = "entity_id", length = 100)
    private String entityId;

    /** JSON configuration for column mappings, etc. */
    @Column(name = "sql_config", columnDefinition = "TEXT")
    private String sqlConfig;

    /** Whether this SQL is active */
    @Column(name = "is_active")
    @Builder.Default
    private Boolean active = true;

    @Column(name = "reg_dttm", length = 20)
    private String regDttm;

    @Column(name = "act_dttm", length = 20)
    private String actDttm;
}
