    name: nexabuilder
  lifecycle:
    # Pairs with server.shutdown=graceful — match K8s
    # terminationGracePeriodSeconds.
    timeout-per-shutdown-phase: 30s

  profiles:
    active: h2  # Default to H2 for development. Use: mysql, postgres, oracle

  jpa:
    open-in-view: false
    hibernate:
      ddl-auto: none  # Liquibase handles schema
    properties:
      hibernate:
        format_sql: true
        default_batch_fetch_size: 100

  liquibase:
    change-log: classpath:db/migration/changelog-master.xml

  servlet:
    multipart:
