public class SqlExecutor {

    private static final Pattern NAMED_PARAMETER = Pattern.compile("(?<!:):([A-Za-z][A-Za-z0-9_]*)\\b");

    private final NamedParameterJdbcTemplate jdbcTemplate;
    private final SqlMetadataRepository sqlMetadataRepository;
    private final SqlDialectResolver dialectResolver;

    /**
     * Execute a SELECT query by SQL ID.
     * Replaces: sqls.getResult(sqlId, params)
     */
    @Transactional(readOnly = true)
    public RecordSet executeQuery(String sqlId, Map<String, Object> params) {
        String sql = resolveSql(sqlId);
        if (sql == null) {
            throw new SqlNotFoundException("SQL not found: " + sqlId);
        }

        log.debug("Executing query [{}]: {}", sqlId, sql);

        List<Map<String, Object>> rows = jdbcTemplate.queryForList(sql, bindMissingParams(sql, params));
        return new RecordSet(rows);
    }

    /**
     * Execute a DML (INSERT/UPDATE/DELETE) by SQL ID.
     * Replaces: sqls.execute(sqlId, data)
     */
    @Transactional
    public int executeDml(String sqlId, Map<String, Object> params) {
        String sql = resolveSql(sqlId);
        if (sql == null) {
            throw new SqlNotFoundException("SQL not found: " + sqlId);
        }

        log.debug("Executing DML [{}]: {}", sqlId, sql);

        return jdbcTemplate.update(sql, bindMissingParams(sql, params));
    }

    /**
     * Execute raw SQL (for admin/migration use only).
     */
    @Transactional(readOnly = true)
    public RecordSet executeRawQuery(String sql, Map<String, Object> params) {
        List<Map<String, Object>> rows = jdbcTemplate.queryForList(sql, bindMissingParams(sql, params));
        return new RecordSet(rows);
    }

    /**
     * Load SQL metadata by ID, resolving the correct dialect.
     */
    @Cacheable(value = "sqlMetadata", key = "#sqlId")
    public String resolveSql(String sqlId) {
        return sqlMetadataRepository.findById(sqlId)
                .map(dialectResolver::resolve)
                .orElse(null);
    }

    private Map<String, Object> bindMissingParams(String sql, Map<String, Object> params) {
        if (sql == null || !sql.contains(":")) {
            return params != null ? params : Collections.emptyMap();
        }
        Map<String, Object> bound = new LinkedHashMap<>();
        if (params != null) {
            bound.putAll(params);
        }
        Matcher matcher = NAMED_PARAMETER.matcher(sql);
        while (matcher.find()) {
            bound.putIfAbsent(matcher.group(1), null);
        }
        return bound;
    }

    public static class SqlNotFoundException extends RuntimeException {
