    <!--
        Soft-delete columns for designer-facing metadata.

        Why three tables? These are the artifacts a designer can lose by
        accident — a misclicked "delete" on /admin/ui-builder or the
        entity admin. Restoring them used to mean rebuilding the JSON
        layout by hand. With deleted_at, DELETE just stamps a timestamp
        and /admin/trash surfaces the row for restore or permanent
        deletion within the retention window.

        Format: yyyyMMddHHmmss (same VARCHAR(20) convention the rest of
        the schema uses for reg_dttm / act_dttm). NULL = live row.
        Non-null = in trash. The /admin/trash listing reads the column
        directly to compute "deleted N days ago" relative timestamps.

        We deliberately do NOT add an index — the column has high
        cardinality (mostly NULL on a healthy system) and the trash
        listing is a single full-scan that filters in-memory, which is
        cheap at this metadata scale (low hundreds of rows).
    -->
    <changeSet id="027-01-soft-delete-list" author="nexabuilder">
        <addColumn tableName="nexa_list">
            <column name="deleted_at" type="VARCHAR(20)"/>
        </addColumn>
    </changeSet>
    <changeSet id="027-02-soft-delete-form" author="nexabuilder">
        <addColumn tableName="nexa_form">
            <column name="deleted_at" type="VARCHAR(20)"/>
        </addColumn>
    </changeSet>
    <changeSet id="027-03-soft-delete-entity" author="nexabuilder">
        <addColumn tableName="nexa_entity">
